<template>
  <section class="frame-location">
    <header><div><small>FILTEREDFRAMES → GEOM → 地点证据</small><h2>从屏幕坐标建立场景</h2></div><span>{{ result ? '地图资料已查证 · 人群仍为推演' : region?.status==='complete' ? '区域地图已查证 · 选择屏幕查看局部' : '本地坐标解析 · 地点待查证' }}</span></header>
    <p>选取工作簿中的 Frame，以 GEOM 坐标核实街道、周边道路与设施，再由大模型解释环境并生成候选人群。库存市场名称、POI 和地理位置冲突时保留原字段与提示。仅选择 Frame 不会改变下方已有模拟，查证并生成后才会应用。</p>
    <div class="actions"><button @click="load(false)" :disabled="busy||disabled">读取 test.xlsx 的 FilteredFrames</button><button v-if="projectId" @click="load(true)" :disabled="busy||disabled">读取当前工作簿 FilteredFrames</button><label class="upload">上传工作簿<input type="file" accept=".xlsx" aria-label="上传地点工作簿" :disabled="busy||disabled" @change="upload"></label></div>
    <p v-if="error" role="alert" class="error">{{ error }}</p>
    <RegionalMap v-if="inventory" :inventory="inventory" :region="region" :selected="selected" :enabled="config?.enabled" :disabled="busy||disabled" @select="selectFrame" @start="startRegion" @analyze="analyzeRegion" />
    <div v-if="inventory" class="frame-inputs"><p>{{ inventory.filename }} · {{ inventory.sheet }} · {{ inventory.total }} 条 Frame · {{ inventory.valid_coordinates }} 条有效坐标</p><label>选择 Frame<select aria-label="选择 FilteredFrames Frame" v-model="selected" :disabled="busy||disabled" @change="result=null"><option v-for="f in inventory.frames" :key="f.key" :value="f.key">{{ f.screen_id || '缺少 ID' }} · {{ f.address || f.city }}{{ f.error?' · 坐标错误':'' }}</option></select></label>
      <dl v-if="frame"><dt>原始 GEOM</dt><dd>{{ frame.fields.GEOM || '缺失' }}</dd><dt>解析坐标</dt><dd>{{ frame.coordinate ? `${frame.coordinate.lat} 纬度 / ${frame.coordinate.lon} 经度 · ${frame.coordinate.crs}` : frame.error }}</dd><dt>库存城市 / 地址</dt><dd>{{ frame.city }} / {{ frame.address }}</dd><dt>库存 POI</dt><dd>{{ frame.poi || '未提供' }}（库存线索，尚未确认）</dd></dl><ul v-if="frame?.warnings.length"><li v-for="w in frame.warnings" :key="w">{{ w }}</li></ul>
      <div class="actions"><label>周边半径<select aria-label="坐标周边查询半径" v-model.number="radius" :disabled="busy||disabled" @change="result=null"><option v-for="r in [200,400,600]" :key="r" :value="r">{{ r }} 米</option></select></label><button class="locate" @click="locate" :disabled="busy||disabled||!frame?.coordinate||!!frame?.error||!config?.enabled">{{ busy?'正在处理…':'核实坐标并用大模型分析' }}</button><a v-if="frame?.coordinate" :href="mapLink" target="_blank" rel="noopener noreferrer">手动在 OpenStreetMap 查看坐标 ↗</a></div>
    </div>
    <div class="lookup-state"><b v-if="config&&!config.enabled">外部地图查询尚未启用：当前不会发送坐标，也不会把模型猜测当成定位结果。</b><p>{{ config?.disclosure }}</p><small>{{ config?.rate_limit }} · <a :href="config?.policy_url" target="_blank" rel="noopener noreferrer">地图服务使用规则</a></small></div>
    <div v-if="result" class="geo-result"><h3>{{ result.locality.city }} · {{ result.locality.community }}</h3><p>地图记录时间 {{ result.evidence.queried_at }} · {{ result.evidence.attribution }}</p><ul class="conflicts"><li v-for="w in result.warnings" :key="w">{{ w }}</li></ul><div class="result-columns"><div><h4>地图返回的事实线索</h4><ul><li v-for="f in result.facts.slice(0,12)" :key="f.id"><a :href="f.url" target="_blank" rel="noopener noreferrer">{{ f.text }}</a></li></ul></div><div><h4>大模型解释 · 非人口事实</h4><p>{{ result.inference.environment_interpretation }}</p><ul><li v-for="role in result.inference.audience_hypotheses" :key="role.name"><b>{{ role.name }}</b>：{{ role.rationale }}</li></ul></div></div><p>{{ result.evidence.limitations.join(' ') }}</p><ul><li v-for="w in result.inference.uncertainties" :key="w">{{ w }}</li></ul><button class="locate" :disabled="disabled||busy" @click="$emit('apply',result)">按此地点生成人群与环境</button><small>应用前，下方仍为已有模拟；应用后需生成新的代表画像，旧记录不会被改写。</small></div>
  </section>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import RegionalMap from './RegionalMap.vue'
import api from '../api'
const props=defineProps({projectId:String,disabled:Boolean})
defineEmits(['apply'])
const inventory=ref(null),selected=ref(''),radius=ref(400),result=ref(null),busy=ref(false),error=ref(''),config=ref(null),region=ref(null)
let timer=null,disposed=false,inventoryVersion=0
const frame=computed(()=>inventory.value?.frames.find(f=>f.key===selected.value))
const mapLink=computed(()=>frame.value?.coordinate?`https://www.openstreetmap.org/?mlat=${frame.value.coordinate.lat}&mlon=${frame.value.coordinate.lon}#map=18/${frame.value.coordinate.lat}/${frame.value.coordinate.lon}`:'')
async function accept(data){const version=++inventoryVersion;clearTimeout(timer);region.value=null;inventory.value=data;selected.value=data.frames.find(f=>!f.error)?.key||data.frames[0]?.key||'';result.value=null;const response=await api.get('/api/world/regions/latest/'+data.id);if(disposed||version!==inventoryVersion)return;region.value=response.data;if(isPending())pollRegion()}
async function load(project){busy.value=true;error.value='';try{await accept((await api.post('/api/world/geo-inventory',project?{project_id:props.projectId}:{})).data)}catch(e){error.value=e.message}finally{busy.value=false}}
async function upload(e){const file=e.target.files[0];if(!file)return;busy.value=true;error.value='';try{const data=new FormData();data.append('file',file);await accept((await api.post('/api/world/geo-inventory',data,{headers:{'Content-Type':'multipart/form-data'}})).data)}catch(e){error.value=e.message}finally{busy.value=false;e.target.value=''}}
async function locate(){busy.value=true;error.value='';result.value=null;try{result.value=(await api.post('/api/world/locate-frame',{inventory_id:inventory.value.id,frame_key:selected.value,radius_m:radius.value,region_id:region.value?.id})).data}catch(e){error.value=e.message}finally{busy.value=false}}
function selectFrame(key){selected.value=key;result.value=null}
function isPending(){return ['queued','running'].includes(region.value?.status)||region.value?.analysis_status==='running'}
async function pollRegion(){clearTimeout(timer);if(disposed||!region.value?.id)return;const id=region.value.id;try{const response=await api.get('/api/world/regions/'+id);if(disposed||region.value?.id!==id)return;region.value=response.data;if(isPending())timer=setTimeout(pollRegion,2000)}catch(e){error.value=e.message}}
async function startRegion(){error.value='';try{const response=await api.post('/api/world/regions',{inventory_id:inventory.value.id});region.value={id:response.data.id,status:'queued'};await pollRegion()}catch(e){error.value=e.message}}
async function analyzeRegion(){error.value='';try{await api.post('/api/world/regions/'+region.value.id+'/analyze');region.value={...region.value,analysis_status:'running'};await pollRegion()}catch(e){error.value=e.message}}
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
onMounted(async()=>{try{config.value=(await api.get('/api/world/location-config')).data;await load(false)}catch(e){error.value=e.message}})
</script>
<style scoped>
.frame-location{background:#ffffff;border:1px solid #dce2e5;border-radius:10px;padding:20px 22px;margin-bottom:20px;color:#191d21}.frame-location header{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.frame-location header small{font-size:10px;color:#191d21;letter-spacing:1px}.frame-location h2{font-size:19px;color:#191d21;margin:8px 0}.frame-location header>span{font-size:11px;color:#191d21}.frame-location p,.frame-location li{font-size:12px;line-height:1.85;overflow-wrap:anywhere}.frame-location a{color:#191d21}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.actions a{font-size:12px}.frame-location button,.upload{background:#f1f5f4;border:1px solid #dce2e5;color:#191d21;padding:9px 12px;border-radius:5px;font-size:12px;cursor:pointer}.frame-location button:disabled{opacity:.45;cursor:not-allowed}.upload input{display:block;font-size:11px;margin-top:6px;max-width:220px}.frame-location select{display:block;width:100%;background:#ffffff;color:#191d21;border:1px solid #dce2e5;border-radius:5px;padding:10px;margin-top:8px}.frame-inputs>label{font-size:12px}.frame-inputs dl{display:grid;grid-template-columns:130px 1fr;gap:12px;background:#ffffff;padding:16px;border-radius:6px;font-size:12px;line-height:1.7}.frame-inputs dt{color:#525b65}.frame-inputs dd{margin:0;overflow-wrap:anywhere}.frame-location ul{padding-left:20px}.lookup-state{border-top:1px solid #dce2e5;padding-top:12px}.lookup-state b{font-size:12px;color:#191d21}.lookup-state small,.geo-result>small{display:block;font-size:11px;color:#525b65;line-height:1.8}.frame-location .error{color:#9a452b}.frame-location .locate{background:#e6f3ed;color:#525b65;border-color:#dce2e5;font-weight:600}.geo-result{margin-top:16px;border-top:1px solid #dce2e5}.geo-result h3{color:#191d21}.conflicts{color:#191d21}.result-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.result-columns>div{background:#ffffff;padding:12px;border-radius:6px}.result-columns ul{max-height:320px;overflow:auto}.result-columns h4{font-size:13px;margin:5px 0}.geo-result>small{margin-top:10px}@media(max-width:750px){.frame-location{padding:16px 12px}.frame-inputs dl{grid-template-columns:1fr;gap:5px}.frame-inputs dd{margin-bottom:10px}.result-columns{grid-template-columns:1fr}.actions{align-items:stretch}.frame-location h2{font-size:17px}}
</style>
